"""
Detect / install Demucs for Advanced film audio enhance (vocal separation).

When an NVIDIA GPU is present, also upgrade to CUDA-enabled PyTorch
(from the official cu124 wheel index) so Demucs can run on GPU.
"""

from __future__ import annotations

import logging
import subprocess
import sys
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.runtime_audio")

DEMUCS_PIP_PACKAGES = ("demucs",)

# Demucs GPU needs CUDA-enabled torch wheels (not the CPU build demucs often pulls).
# Prefer cu126: matches current PyPI torch majors (e.g. 2.13); cu124 tops out at 2.6
# and `pip install --upgrade` will refuse to "downgrade" 2.13+cpu → 2.6+cu124.
#
# Aliyun hosts the actual .whl files (flat directory). SJTU/official indexes often
# redirect downloads to download.pytorch.org / R2, which stalls for many CN users.
TORCH_CUDA_PACKAGES = ("torch", "torchaudio")
TORCH_CUDA_FIND_LINKS = (
    "https://mirrors.aliyun.com/pytorch-wheels/cu126/",
    "https://mirrors.aliyun.com/pytorch-wheels/cu124/",
)
TORCH_CUDA_INDEX_URLS = (
    "https://download.pytorch.org/whl/cu126",
    "https://download.pytorch.org/whl/cu124",
    "https://download.pytorch.org/whl/cu128",
    "https://mirror.sjtu.edu.cn/pytorch-wheels/cu126",
    "https://mirror.sjtu.edu.cn/pytorch-wheels/cu124",
)


def _probe_torch_cuda() -> dict[str, Any]:
    torch_cuda = False
    torch_cuda_name = ""
    torch_version = ""
    torch_error = ""
    try:
        import torch  # type: ignore

        torch_version = str(getattr(torch, "__version__", "") or "").strip()
        torch_cuda = bool(torch.cuda.is_available())
        if torch_cuda:
            try:
                torch_cuda_name = str(torch.cuda.get_device_name(0) or "").strip()
            except Exception:
                torch_cuda_name = ""
    except OSError as err:
        # WinError 4551: Smart App Control / WDAC blocked unsigned torch DLL.
        torch_error = str(err)
        winerr = getattr(err, "winerror", None)
        if winerr == 4551 or "4551" in torch_error:
            torch_error = (
                "Windows 应用程序控制策略已阻止加载 torch DLL（常见于「智能应用控制」）。"
                "请到：Windows 安全中心 → 应用和浏览器控制 → 智能应用控制 → 关闭；"
                "或将引擎 .venv 目录加入杀毒/Defender 排除项后重启应用。"
            )
    except Exception as err:
        torch_error = str(err)
    return {
        "torchCuda": torch_cuda,
        "torchCudaName": torch_cuda_name,
        "torchVersion": torch_version,
        "torchError": torch_error,
    }


def _has_nvidia_gpu() -> bool:
    try:
        from .device import detect_device

        return bool(detect_device().get("hasCuda"))
    except Exception:
        return False


def _demucs_pip_command() -> str:
    from .runtime_extras import ALIYUN_PIP

    index, host = ALIYUN_PIP
    return (
        f"python -m pip install --upgrade -i {index} --trusted-host {host} demucs"
    )


def _torch_cuda_pip_command(index_url: str | None = None) -> str:
    pkgs = " ".join(TORCH_CUDA_PACKAGES)
    if index_url:
        return (
            f"python -m pip install --upgrade --force-reinstall {pkgs} --index-url {index_url}"
        )
    links = TORCH_CUDA_FIND_LINKS[0]
    # force-reinstall: CPU builds share the same X.Y.Z as CUDA wheels; upgrade alone skips.
    return (
        f"python -m pip install --upgrade --force-reinstall {pkgs} "
        f"--find-links {links} --no-index"
    )


def probe_audio_separate() -> dict[str, Any]:
    """Summarize Demucs / vocal-separation readiness (incl. PyTorch CUDA)."""
    torch_info = _probe_torch_cuda()
    torch_cuda = bool(torch_info.get("torchCuda"))
    torch_cuda_name = str(torch_info.get("torchCudaName") or "")
    torch_error = str(torch_info.get("torchError") or "").strip()
    has_gpu = _has_nvidia_gpu()

    try:
        import demucs  # type: ignore

        version = str(getattr(demucs, "__version__", "") or "").strip() or "unknown"
        if torch_error:
            status = "need_torch_cuda"
            hint = (
                f"Demucs 已安装（{version}），但无法加载 PyTorch。"
                f"{torch_error}"
            )
        elif has_gpu and not torch_cuda:
            status = "need_torch_cuda"
            hint = (
                f"Demucs 已安装（{version}），但引擎 PyTorch 无 CUDA。"
                "请重新「下载 Demucs」/「补齐 CUDA PyTorch」，或手动执行："
                f" {_torch_cuda_pip_command()}"
            )
        elif torch_cuda:
            status = "ready"
            hint = (
                f"Demucs 已安装（{version}），GPU 可用"
                + (f"：{torch_cuda_name}" if torch_cuda_name else "")
            )
        else:
            status = "ready"
            hint = (
                f"Demucs 已安装（{version}）；未检测到 NVIDIA GPU，人声分离将使用 CPU"
            )
        return {
            "ok": True,
            "status": status,
            "installed": True,
            "package": "demucs",
            "version": version,
            "hasCudaGpu": has_gpu,
            "torchCuda": torch_cuda,
            "torchCudaName": torch_cuda_name,
            "torchVersion": torch_info.get("torchVersion") or "",
            "torchError": torch_error,
            "hint": hint,
            "packages": list(DEMUCS_PIP_PACKAGES),
            "torchCudaPackages": list(TORCH_CUDA_PACKAGES),
            "pipCommand": _demucs_pip_command(),
            "torchCudaPipCommand": _torch_cuda_pip_command(),
        }
    except Exception as err:
        return {
            "ok": True,
            "status": "need_install",
            "installed": False,
            "package": "demucs",
            "version": "",
            "hasCudaGpu": has_gpu,
            "torchCuda": torch_cuda,
            "torchCudaName": torch_cuda_name,
            "torchVersion": torch_info.get("torchVersion") or "",
            "torchError": torch_error,
            "hint": (
                "未安装 Demucs。请在设置中「下载 Demucs（人声分离）」"
                "（有 GPU 时会同时安装 CUDA 版 PyTorch）。"
            ),
            "error": str(err),
            "packages": list(DEMUCS_PIP_PACKAGES),
            "torchCudaPackages": list(TORCH_CUDA_PACKAGES),
            "pipCommand": _demucs_pip_command(),
            "torchCudaPipCommand": _torch_cuda_pip_command(),
        }


def _run_pip(
    args: list[str],
    *,
    timeout: int = 3600,
) -> subprocess.CompletedProcess[str]:
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("ensure_audio_separate pip: %s", " ".join(cmd))
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout,
        check=False,
    )


def _install_demucs(*, force: bool = False) -> dict[str, Any]:
    from .runtime_extras import (
        PIP_MIRRORS,
        is_mirror_http_deny,
        note_mirror_denied,
        order_pip_mirrors,
        probe_pip_mirrors,
    )

    mirrors = order_pip_mirrors(probe_pip_mirrors(PIP_MIRRORS), mirrors=PIP_MIRRORS)
    last_err = ""
    tried: list[str] = []
    for index, host in mirrors:
        args = [
            "install",
            "--upgrade",
            "-i",
            index,
            "--trusted-host",
            host,
            *DEMUCS_PIP_PACKAGES,
        ]
        if force:
            args.insert(1, "--force-reinstall")
        tried.append(host)
        try:
            proc = _run_pip(args, timeout=3600)
        except subprocess.TimeoutExpired:
            last_err = f"安装 Demucs 超时（镜像 {host}）"
            continue
        if proc.returncode == 0:
            return {"ok": True, "installed": list(DEMUCS_PIP_PACKAGES), "mirror": host}
        err_tail = (proc.stderr or proc.stdout or "").strip()[-1200:]
        last_err = err_tail or f"exit {proc.returncode}"
        if is_mirror_http_deny(last_err):
            note_mirror_denied(host)
            _log.warning("demucs pip HTTP deny via %s, switching mirror", host)
        else:
            _log.warning("demucs pip failed via %s: %s", host, last_err[:300])

    tried_s = " → ".join(tried) if tried else "无"
    return {
        "ok": False,
        "code": "AUDIO_SEPARATE_INSTALL_FAILED",
        "message": f"Demucs 安装失败（已尝试镜像：{tried_s}）。{last_err}",
        "stderr": last_err,
        "mirrorsTried": tried,
    }


def _verify_torch_cuda_after_install(source: str) -> dict[str, Any] | None:
    """Return success dict if CUDA torch works, else None and leave a note in logs."""
    try:
        from .runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception as err:
        _log.warning("inject_nvidia_lib_path after torch cuda: %s", err)
    torch_info = _probe_torch_cuda()
    if torch_info.get("torchCuda"):
        return {
            "ok": True,
            "installed": list(TORCH_CUDA_PACKAGES),
            "indexUrl": source,
            "torchVersion": torch_info.get("torchVersion") or "",
            "torchCudaName": torch_info.get("torchCudaName") or "",
        }
    _log.warning(
        "installed via %s but torch.cuda.is_available() is False (version=%s)",
        source,
        torch_info.get("torchVersion") or "?",
    )
    return None


def _install_torch_cuda(*, force: bool = False) -> dict[str, Any]:
    """
    Replace CPU torch (often pulled by demucs / PyPI) with CUDA wheels.

    Always force-reinstall: a newer CPU build (e.g. 2.13.0+cpu) otherwise blocks
    older CUDA tags on cu124 (max 2.6), and same X.Y.Z+cu* may look "satisfied".

    Prefer Aliyun --find-links (hosts real .whl). PEP 503 indexes often redirect
    the download to download.pytorch.org which stalls in CN.
    """
    del force  # always force-reinstall CPU→CUDA; kept for call-site compatibility
    last_err = ""

    attempts: list[tuple[str, list[str]]] = []
    for links in TORCH_CUDA_FIND_LINKS:
        attempts.append(
            (
                links,
                [
                    "install",
                    "--upgrade",
                    "--force-reinstall",
                    *TORCH_CUDA_PACKAGES,
                    "--find-links",
                    links,
                    "--no-index",
                ],
            )
        )
    for index_url in TORCH_CUDA_INDEX_URLS:
        attempts.append(
            (
                index_url,
                [
                    "install",
                    "--upgrade",
                    "--force-reinstall",
                    *TORCH_CUDA_PACKAGES,
                    "--index-url",
                    index_url,
                ],
            )
        )

    for source, args in attempts:
        try:
            # Per-source timeout so a stalled CDN does not block forever.
            proc = _run_pip(args, timeout=1800)
        except subprocess.TimeoutExpired:
            last_err = f"timeout via {source}"
            _log.warning("%s", last_err)
            continue
        if proc.returncode == 0:
            ok = _verify_torch_cuda_after_install(source)
            if ok:
                return ok
            last_err = (
                f"installed via {source} but torch.cuda.is_available() is False"
            )
            continue
        last_err = (proc.stderr or proc.stdout or "").strip()[-1200:]
        _log.warning("torch CUDA install failed via %s: %s", source, last_err[:200])

    return {
        "ok": False,
        "code": "TORCH_CUDA_INSTALL_FAILED",
        "message": (
            "CUDA 版 PyTorch 安装失败。可手动执行："
            f" {_torch_cuda_pip_command()}；详情：{last_err}"
        ),
        "stderr": last_err,
    }


def ensure_audio_separate(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Install Demucs (+ CUDA PyTorch when NVIDIA GPU is present)."""

    def progress(ev: dict[str, Any]) -> None:
        if on_progress:
            on_progress(ev)

    probe = probe_audio_separate()
    progress(
        {
            "type": "progress",
            "stage": "probe",
            "percent": 5,
            "detail": probe.get("hint") or "检测 Demucs…",
            "probe": probe,
        }
    )

    status = str(probe.get("status") or "")
    if status == "ready" and not force:
        return {
            "ok": True,
            "skipped": True,
            "reason": "already_ready",
            "probe": probe,
            "message": probe.get("hint"),
        }

    installed: list[str] = []
    need_demucs = force or status == "need_install" or not probe.get("installed")
    need_torch = force or status == "need_torch_cuda" or (
        bool(probe.get("hasCudaGpu")) and not bool(probe.get("torchCuda"))
    )

    if need_demucs:
        progress(
            {
                "type": "progress",
                "stage": "download",
                "percent": 12,
                "detail": "正在安装 Demucs（人声分离，含依赖，体积较大，请稍候）…",
                "packages": list(DEMUCS_PIP_PACKAGES),
            }
        )
        demucs_res = _install_demucs(force=force)
        if not demucs_res.get("ok"):
            return {
                **demucs_res,
                "probe": probe_audio_separate(),
            }
        installed.extend(demucs_res.get("installed") or [])
        # demucs often pulls CPU torch — always try CUDA torch next if GPU present
        need_torch = need_torch or _has_nvidia_gpu()

    torch_res: dict[str, Any] | None = None
    if need_torch and _has_nvidia_gpu():
        progress(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "percent": 48,
                "detail": (
                    "正在安装 CUDA 版 PyTorch（Demucs GPU，约 2GB+，请稍候）…"
                ),
                "packages": list(TORCH_CUDA_PACKAGES),
                "indexUrls": list(TORCH_CUDA_INDEX_URLS),
            }
        )
        torch_res = _install_torch_cuda(force=force)
        if torch_res.get("ok"):
            installed.extend(torch_res.get("installed") or [])
        else:
            # Demucs itself may be usable on CPU — report soft failure with guidance.
            after_partial = probe_audio_separate()
            if after_partial.get("installed"):
                progress(
                    {
                        "type": "progress",
                        "stage": "torch_cuda",
                        "percent": 88,
                        "detail": torch_res.get("message")
                        or "CUDA torch 安装失败，Demucs 仍可用（CPU）",
                    }
                )
                return {
                    "ok": True,
                    "skipped": False,
                    "partial": True,
                    "code": torch_res.get("code"),
                    "installed": installed,
                    "probe": after_partial,
                    "message": (
                        (after_partial.get("hint") or "Demucs 已安装")
                        + "；"
                        + str(torch_res.get("message") or "CUDA torch 未装上")
                    ),
                    "torchCuda": torch_res,
                }
            return {
                **torch_res,
                "installed": installed,
                "probe": after_partial,
            }
    elif need_torch and not _has_nvidia_gpu():
        progress(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "percent": 70,
                "detail": "未检测到 NVIDIA GPU，跳过 CUDA 版 PyTorch",
            }
        )

    progress(
        {
            "type": "progress",
            "stage": "verify",
            "percent": 92,
            "detail": "正在校验 Demucs / PyTorch CUDA…",
        }
    )

    after = probe_audio_separate()
    if not after.get("installed"):
        return {
            "ok": False,
            "code": "AUDIO_SEPARATE_INSTALL_FAILED",
            "probe": after,
            "installed": installed,
            "message": after.get("hint") or "Demucs 安装后仍不可用",
        }

    partial = after.get("status") == "need_torch_cuda"
    detail = after.get("hint") or "Demucs 已就绪"
    progress(
        {
            "type": "done" if not partial else "progress",
            "stage": "done",
            "percent": 100,
            "detail": detail,
            "probe": after,
        }
    )
    return {
        "ok": True,
        "skipped": False,
        "partial": partial,
        "installed": installed,
        "probe": after,
        "message": detail,
        "torchCuda": torch_res,
    }
